import java.util.*;
public class PublicChecks {public record Observation(String actual,boolean passed){}
static final String NORMAL_NAME="FIFO при росте: два типа";
static final String NORMAL_WHAT="Короткая трасса сохраняет оставшиеся элементы; несколько ростов предъявляются отдельно.";
static final String NORMAL_INPUT="String[2]: А,Б,В/get/Г/get3; Integer[2]:10,20,30/get/40/get3";
static final String NORMAL_EXPECTED="А,Б,В,Г;10,20,30,40; размеры/текст свободны.";
static final String BOUNDARY_NAME="Начальная длина один";
static final String BOUNDARY_WHAT="Предзаполненный массив задаёт пустую очередь, рост сохраняет7,8.";
static final String BOUNDARY_INPUT="Integer[]{99}:get/put7/put8/get/get/get";
static final String BOUNDARY_EXPECTED="null с сообщением;7,8;null с сообщением; исходное99 не извлекается.";
public static Observation observeNormal(){Object s=TaskBinding.publicQueue(0,new String[2]);Object i=TaskBinding.publicQueue(1,new Integer[2]);Object[] got=new Object[8];String output=PublicMessages.capture(()->{TaskBinding.put(s,"А");TaskBinding.put(s,"Б");TaskBinding.put(s,"В");got[0]=TaskBinding.get(s);TaskBinding.put(s,"Г");for(int k=1;k<4;k++)got[k]=TaskBinding.get(s);TaskBinding.put(i,10);TaskBinding.put(i,20);TaskBinding.put(i,30);got[4]=TaskBinding.get(i);TaskBinding.put(i,40);for(int k=5;k<8;k++)got[k]=TaskBinding.get(i); });Object[] expected={"А","Б","В","Г",10,20,30,40};return new Observation("Извлечено="+Arrays.toString(got)+"; вывод (текст свободен)="+PublicOutput.escaped(output),Arrays.equals(got,expected));}
public static Observation observeBoundary(){Object q=TaskBinding.publicQueue(1,new Integer[]{99});Object[] got=new Object[4];String initial=PublicMessages.capture(()->got[0]=TaskBinding.get(q));String add=PublicMessages.capture(()->TaskBinding.put(q,7));String middle=PublicMessages.capture(()->{TaskBinding.put(q,8);got[1]=TaskBinding.get(q);got[2]=TaskBinding.get(q);});String last=PublicMessages.capture(()->got[3]=TaskBinding.get(q));return new Observation("Извлечено="+Arrays.toString(got)+"; первый отказ="+PublicOutput.escaped(initial)+"; успешные действия="+PublicOutput.escaped(add+middle)+"; последний отказ="+PublicOutput.escaped(last),Arrays.equals(got,new Object[]{null,7,8,null})&&!initial.isBlank()&&!last.isBlank());}
public static void checkNormal(Observation o){if(!o.passed())throw new AssertionError("Сопоставьте обычное наблюдение с условием.");}
public static void checkBoundary(Observation o){if(!o.passed())throw new AssertionError("Сопоставьте опубликованную границу с условием.");}
static int example(boolean normal){System.out.println("Сценарий: "+(normal?NORMAL_NAME:BOUNDARY_NAME));System.out.println("Что наблюдаем: "+(normal?NORMAL_WHAT:BOUNDARY_WHAT));System.out.println("Вход/действие: "+(normal?NORMAL_INPUT:BOUNDARY_INPUT));System.out.println("Ожидается: "+(normal?NORMAL_EXPECTED:BOUNDARY_EXPECTED));try{var o=normal?observeNormal():observeBoundary();System.out.println("Получено: "+o.actual());System.out.println(o.passed()?"Статус: наблюдаемое свойство соответствует; исходник и объяснение оценивает преподаватель.":"Статус: наблюдаемое свойство не соответствует.");return o.passed()?0:1;}catch(LinkageError e){System.out.println("Статус: привязка или среда не подготовлена; требуется ручная проверка, оценки нет.");return 2;}catch(RuntimeException e){System.out.println("Статус: операция или пример привязки не завершены корректно. Тип: "+e.getClass().getSimpleName());return 1;}catch(Error e){System.out.println("Статус: ошибка выполнения операции. Тип: "+e.getClass().getSimpleName());return 1;}}
public static void main(String[] args){int status=Math.max(example(true),example(false));if(status!=0)System.exit(status);}}
